const bytes = new TextEncoder().encode('€');
const a = bytes.subarray(0, 2), b = bytes.subarray(2);
const plain = new TextDecoder();
const r1 = plain.decode(a) + plain.decode(b);
console.log(r1.length, r1 === '€');
const streaming = new TextDecoder();
const r2 = streaming.decode(a, { stream: true }) + streaming.decode(b);
console.log(r2.length, r2 === '€');

